rs=h.get('relative_strength_shadow') or {}; assert rs.get('version')=='MARKET_SECTOR_RS_SHADOW_V1' and rs.get('auto_apply') is False and rs.get('buy_effect') is False,rs
rsl=h.get('rs_leader_table') or {}; assert rsl.get('version')=='RS_LEADER_TABLE_V2' and int(rsl.get('kiwoom_extra_requests') or 0)==0 and rsl.get('buy_effect') is False,rsl
files=h.get('data_files') or {}
for k in ('buy_signals','exit_positions','nxt_alerts','nxt_second_wave','nxt_next_day_picks','nxt_daily_strong_ledger','manual_positions','evidence_report','replay_journal_today','prospective_observations','prospective_outcomes','nxt_market_top1_audit','eod_screen_snapshot'):
    assert k in files,(k,files)
